pub broadcast proof fn lemma_ref_obeys_deep_eq<T: PartialEq + DeepView>()
    requires
        obeys_deep_eq::<T>(),
    ensures
        #[trigger] obeys_deep_eq::<&T>(),
{
    reveal(obeys_deep_eq);
